                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Personal Information</strong>
                        <a href="javascript:void(0)" @onclick="() => GoToStep(0)">Edit</a>
                    </div>
                    <div class="card-body">
                        <p><strong>Name:</strong> @FullName</p>
                        <p><strong>Email:</strong> @Email</p>
                        <p><strong>Phone:</strong> @Phone</p>
                        <p><strong>Address:</strong> @Address</p>
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Work History</strong>
                        <a href="javascript:void(0)" @onclick="() => GoToStep(1)">Edit</a>
                    </div>
                    <div class="card-body">
                        @foreach (var entry in WorkEntries)
                        {
                            <div class="mb-3 pb-3 border-bottom">
                                <p><strong>@entry.Title</strong> at @entry.Company</p>
                                <p class="text-muted">
                                    @entry.StartDate.ToString("MMM yyyy") &mdash;
                                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                                </p>
                                @if (!string.IsNullOrWhiteSpace(entry.Description))
                                {
                                    <p>@entry.Description</p>
                                }
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>References</strong>
                        <a href="javascript:void(0)" @onclick="() => GoToStep(2)">Edit</a>
                    </div>
                    <div class="card-body">
                        @foreach (var reference in References)
                        {
                            <div class="mb-2">
                                <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                                <p class="text-muted">@reference.Email | @reference.Phone</p>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Cover Letter</strong>
                        <a href="javascript:void(0)" @onclick="() => GoToStep(3)">Edit</a>
                    </div>
                    <div class="card-body">
                        <p style="white-space: pre-wrap;">@CoverLetter</p>
                    </div>
                </div>

                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PrevStep">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
