.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 1.5rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step.future {
    opacity: 0.4;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #6c757d;
    color: #6c757d;
    background: white;
    transition: all 0.2s;
}

.step.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: white;
}

.step.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: white;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    font-weight: 500;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 700;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #198754;
}

.step-content {
    max-width: 800px;
    margin: 0 auto;
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 1.5rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step.future {
    opacity: 0.4;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #6c757d;
    color: #6c757d;
    background: white;
    transition: all 0.2s;
}

.step.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: white;
}

.step.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: white;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    font-weight: 500;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 700;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #198754;
}

.step-content {
    max-width: 800px;
    margin: 0 auto;
}

